model:
rachana: 1
sutra: financed-emissions
version: 1
description: 
match: { kind: financed-emissions, priority: 10 }
title: { pill: "Climate · Financed emissions", id: "$.resultId" }
strip:
  - { label: "Book", bind: "$.book" }
  - { label: "Financed (tCO2e)", bind: "$.financed", fmt: "amount0", emphasis: true }
  - { label: "Exposure", bind: "$.exposure", fmt: "compact" }
  - { label: "Intensity (t per USD m)", bind: "$.intensity", fmt: "amount0" }
  - { label: "PCAF data quality", bind: "$.dataQuality", fmt: "price2" }
panels:
  - id: byCounterparty
    kind: table
    title: "By counterparty"
    key: "F2"
    rows: "$.byCounterparty"
    columns:
      - { label: "Counterparty", bind: "@.counterparty" }
      - { label: "Exposure", bind: "@.exposure", fmt: "compact" }
      - { label: "Attribution", bind: "@.attribution", fmt: "pct2" }
      - { label: "Financed (tCO2e)", bind: "@.financed", fmt: "amount0", total: true }
      - { label: "Score", bind: "@.dataQuality" }
  - id: bySector
    kind: hbar
    title: "By sector (tCO2e)"
    area: right
    rows: "$.bySector"
    label: "sector"
    value: "financed"
    fmt: "amount0"
  - id: built
    kind: provenance
    title: "How this view was built"
  - id: refs
    kind: links
    title: "Linked entities"
    code: "REFS"
    area: right
keys: { F7: "link($.book, 'book')", F8: "impact", F9: "raw" }
